import{_ as t,c as a,o as s,ah as i}from"./chunks/framework.DaDXF32t.js";const g=JSON.parse('{"title":"Telegram 推送","description":"","frontmatter":{},"headers":[],"relativePath":"usage_doc/telegram_push.md","filePath":"usage_doc/telegram_push.md","lastUpdated":1791622929000}'),o={name:"usage_doc/telegram_push.md"};function l(r,e,n,d,h,p){return s(),a("div",null,e[0]||(e[0]=[i(`<h1 id="telegram-推送" tabindex="-1">Telegram 推送 <a class="header-anchor" href="#telegram-推送" aria-label="Permalink to “Telegram 推送”">​</a></h1><p>BAAS 支持把 <strong>运行出错</strong> 和 <strong>任务完成</strong> 的通知推送到 Telegram 机器人会话，适合挂机时用手机接收状态。</p><h2 id="功能入口" tabindex="-1">功能入口 <a class="header-anchor" href="#功能入口" aria-label="Permalink to “功能入口”">​</a></h2><p>GUI: 主界面 -&gt; 设置 -&gt; <strong>推送配置</strong>，在底部四个 Telegram 字段中填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>Telegram Bot Token</td><td>机器人的 Token，形如 <code>123456:ABC-DEF...</code>；留空则不启用</td></tr><tr><td>Telegram Chat ID</td><td>接收消息的会话 ID</td></tr><tr><td>Telegram 代理</td><td>形如 <code>http://127.0.0.1:7890</code>；国内直连通常不可达，一般需要填</td></tr><tr><td>Telegram API 地址</td><td>自定义 API 域名，留空使用 <code>https://api.telegram.org</code></td></tr></tbody></table><p>只有 <strong>Bot Token 和 Chat ID 同时填写</strong> 时，Telegram 推送才会生效；其他推送渠道（Server酱 / 飞书 / 企业微信）互不影响，可以同时启用。</p><h2 id="获取-bot-token" tabindex="-1">获取 Bot Token <a class="header-anchor" href="#获取-bot-token" aria-label="Permalink to “获取 Bot Token”">​</a></h2><ol><li>在 Telegram 中搜索 <strong>@BotFather</strong> 并关注。</li><li>发送 <code>/newbot</code>，按提示为机器人取名。</li><li>创建成功后 BotFather 会返回一段 Bot Token，复制保存。</li></ol><h2 id="获取-chat-id" tabindex="-1">获取 Chat ID <a class="header-anchor" href="#获取-chat-id" aria-label="Permalink to “获取 Chat ID”">​</a></h2><ol><li>给你刚创建的机器人发送任意一条消息（例如 <code>/start</code>）。</li><li>在浏览器打开 <code>https://api.telegram.org/bot&lt;你的Token&gt;/getUpdates</code>。</li><li>在返回的 JSON 中找到 <code>message.chat.id</code>，这个数字就是 Chat ID。</li></ol><blockquote><p>注意：必须是你<strong>发给机器人</strong>的会话；机器人不会主动发消息，如果 <code>getUpdates</code> 返回 <code>[]</code>，说明还没有给它发过消息。</p></blockquote><h2 id="本地验证-不依赖游戏" tabindex="-1">本地验证（不依赖游戏） <a class="header-anchor" href="#本地验证-不依赖游戏" aria-label="Permalink to “本地验证（不依赖游戏）”">​</a></h2><p>在项目根目录用 <code>.venv</code> 的 Python 跑 demo，真实发送一条测试消息：</p><div class="language-bat"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\python.exe develop_tools\\demo_telegram_push.py --offline</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\python.exe develop_tools\\demo_telegram_push.py</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\python.exe develop_tools\\demo_telegram_push.py --token </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --chat-id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHAT_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> --proxy http://127.0.0.1:7890</span></span></code></pre></div><p>凭证来源优先级：命令行参数 &gt; 环境变量（<code>BAAS_TELEGRAM_BOT_TOKEN</code> / <code>BAAS_TELEGRAM_CHAT_ID</code> / <code>BAAS_TELEGRAM_PROXY</code> / <code>BAAS_TELEGRAM_API</code>）&gt; <code>config/&lt;region&gt;/config.json</code>。</p><p>跑离线单元测试（不需要网络）：</p><div class="language-bat"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\python.exe -m unittest develop_tools.test.test_telegram_push -v</span></span></code></pre></div><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to “常见问题”">​</a></h2><ul><li><strong>发送失败，日志只有 <code>push exception: ConnectionError</code></strong>：网络到不了 Telegram，填代理；日志中不会打印 Token / URL，便于排查。</li><li><strong>日志 <code>push failed: chat not found</code></strong>：Chat ID 填错，或该会话是群组但机器人不在群里。</li><li><strong>日志 <code>push failed: Unauthorized</code></strong>：Token 错误或被 BotFather 重置过。</li><li><strong>代理有效但偶尔超时</strong>：脚本默认 30 秒超时，超时只记一条错误日志，不会阻塞任务运行。</li></ul>`,19)]))}const k=t(o,[["render",l]]);export{g as __pageData,k as default};
